package com.northstar.crm.ui;
import com.northstar.crm.domain.*;import com.northstar.crm.service.EscalationService;import com.vaadin.flow.component.UI;import com.vaadin.flow.component.combobox.ComboBox;import com.vaadin.flow.component.grid.Grid;import com.vaadin.flow.component.orderedlayout.*;import com.vaadin.flow.component.textfield.TextField;import com.vaadin.flow.data.renderer.ComponentRenderer;import com.vaadin.flow.router.*;import jakarta.annotation.security.PermitAll;import java.util.*;import static com.northstar.crm.domain.DomainTypes.*;
@Route(value="escalations",layout=MainLayout.class)@PageTitle("Escalations · Northstar")@PermitAll public class EscalationsView extends VerticalLayout {private final EscalationService service;private final Grid<Escalation> grid=new Grid<>();private final TextField search=UiKit.search("Search requests");private final ComboBox<EscalationStatus> status=new ComboBox<>("Status");private final ComboBox<Severity> severity=new ComboBox<>("Severity");public EscalationsView(EscalationService s){service=s;status.setItems(EscalationStatus.values());status.setClearButtonVisible(true);severity.setItems(Severity.values());severity.setClearButtonVisible(true);search.addValueChangeListener(e->refresh());status.addValueChangeListener(e->refresh());severity.addValueChangeListener(e->refresh());grid.addColumn(Escalation::getSubject).setHeader("Request").setFlexGrow(2);grid.addColumn(new ComponentRenderer<>(e->UiKit.badge(e.getSeverity()))).setHeader("Severity");grid.addColumn(new ComponentRenderer<>(e->UiKit.badge(e.getStatus()))).setHeader("Status");grid.addColumn(e->e.getCreatedAt().atZone(java.time.ZoneId.systemDefault()).toLocalDate()).setHeader("Opened");grid.addColumn(e->e.getAssignedAgentId()==null?"Unassigned":"Assigned").setHeader("Owner");grid.addItemClickListener(e->UI.getCurrent().navigate("escalations/"+e.getItem().getId()));var filters=new HorizontalLayout(search,status,severity);filters.setAlignItems(Alignment.END);var panel=new VerticalLayout(filters,grid);panel.addClassName("panel");add(UiKit.page("SUPPORT WORKFLOW","Escalation queue","Assigned requests with SLA-like age, customer replies and internal handover notes.",panel));setPadding(false);setSizeFull();refresh();}private void refresh(){var q=search.getValue().toLowerCase();grid.setItems(service.queue().stream().filter(e->e.getSubject().toLowerCase().contains(q)).filter(e->status.getValue()==null||e.getStatus()==status.getValue()).filter(e->severity.getValue()==null||e.getSeverity()==severity.getValue()).toList());}}
